INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url) VALUES ('ex_dumbbell_front_raise', 'نشر جلو با دمبل جفت', 'Dumbbell Front Raise', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'دلتوئید قدامی (جلوی شانه)', 'بخش بالایی سینه', '۱. دمبل‌ها را تا ارتفاع چشم بالا آورده و با کنترل پایین ببرید.', '/gifs/0310.gif');
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url) VALUES ('ex_barbell_front_raise', 'نشر جلو با هالتر', 'Barbell Front Raise', 'shoulders', 'سرشانه', 'barbell', 'هالتر', 'دلتوئید قدامی', 'سینه فوقانی', '۱. هالتر را با دستان به عرض شانه تا ارتفاع دید چشم بالا بکشید.', '/gifs/0041.gif');
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url) VALUES ('ex_cable_face_pull', 'فیس‌پول با طناب سیم‌کش', 'Cable Face Pull', 'shoulders', 'سرشانه', 'cable', 'سیم‌کش', 'دلتوئید خلفی (پشت سرشانه) و سلامت روتاتور کاف', 'بخش بالایی پشت', '۱. طناب را در سطح پیشانی تنظیم کرده و دو سر طناب را به سمت گوش‌ها بکشید.', '/gifs/0184.gif');
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url) VALUES ('ex_dumbbell_rear_delt_fly', 'نشر خم دمبل (دلتوئید خلفی)', 'Dumbbell Rear Delt Fly', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'بخش پشتی سرشانه', 'عضلات رومبوئید', '۱. بالاتنه را خم کرده و دمبل‌ها را به طرفین مثل بال پرنده باز کنید.', '/gifs/0377.gif');
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url) VALUES ('ex_arnold_press', 'پرس سرشانه آرنولدی با دمبل', 'Arnold Dumbbell Press', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'درگیری همزمان سرشانه قدامی و جانبی', 'پشت بازو', '۱. حرکت را با مچ‌های رو به بدن آغاز کرده و همزمان با بالا بردن مچ‌ها را به بیرون بچرخانید.', '/gifs/0013.gif');
