INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url) VALUES ('ex_ez_bar_curl', 'جلو بازو با میله خم EZ', 'EZ-Bar Bicep Curl', 'arms', 'بازو', 'barbell', 'هالتر', 'جلو بازو و کاهش فشار روی مچ دست', 'براکیالیس', '۱. روی خمش‌های میله EZ دست بگذارید و با انقباض کامل بالا بیاورید.', '/gifs/0040.gif');
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url) VALUES ('ex_incline_dumbbell_curl', 'جلو بازو دمبل روی میز شیبدار', 'Incline Dumbbell Curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'سر بلند عضله جلو بازو (پیک بایسپس)', 'ساعد', '۱. روی نیمکت شیبدار تکیه دهید و دست‌ها را در حالت آویزان جمع کنید.', '/gifs/0315.gif');
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url) VALUES ('ex_dumbbell_hammer_curl', 'جلو بازو دمبل چکشی', 'Dumbbell Hammer Curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'عضله براکیورادیالیس و ضخامت بازو و ساعد', 'بایسپس', '۱. دمبل‌ها را به حالت عمودی (کف دست رو به هم) به سمت شانه بالا بکشید.', '/gifs/0313.gif');
