INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url) VALUES ('ex_cable_bicep_curl', 'جلو بازو با سیم‌کش ایستاده', 'Standing Cable Bicep Curl', 'arms', 'بازو', 'cable', 'سیم‌کش', 'تنش یکنواخت در تمام طول دامنه جلو بازو', 'ساعد', '۱. دسته سیم‌کش را گرفته و با آرنج ثابت به سمت چانه جمع کنید.', '/gifs/0868.gif');
