INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url) VALUES ('ex_triceps_bar_pushdown', 'پشت بازو سیم‌کش با میله صاف', 'Triceps Straight-Bar Pushdown', 'arms', 'بازو', 'cable', 'سیم‌کش', 'عضله سه سر بازویی (پشت بازو)', 'مچ دست', '۱. با حفظ آرنج‌ها در کنار بدن میله را به سمت پایین صاف کنید.', '/gifs/0240.gif');
