INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url) VALUES ('ex_hanging_leg_raise', 'زیر شکم خلبانی آویزان از بارفیکس', 'Hanging Leg Raise', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'بخش تحتانی عضلات شکم و فلکسورهای لگن', 'ساعد، عضلات شانه', '۱. از بارفیکس آویزان شده و بدون تاب پاها را تا زاویه ۹۰ درجه بالا بیاورید.', '/gifs/0472.gif');
