INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url) VALUES ('ex_russian_twist', 'چرخش روسی (راشن توئیست)', 'Russian Twist', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'عضلات مورب شکمی (پهلوها)', 'عضله راست شکمی', '۱. در حالت V بنشینید و بالاتنه را به صورت متناوب به چپ و راست بچرخانید.', '/gifs/0687.gif');
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url) VALUES ('ex_ab_wheel_rollout', 'رول‌اوت شکم با چرخ تمرین (Ab Wheel)', 'Ab Wheel Rollout', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'کل زنجیره قدامی شکم و میان‌تنه ضد اکستنشن', 'سرشانه، زیربغل', '۱. زانو زده و چرخ را تا کشش کامل به جلو برانید و با انقباض شکم بازگردید.', '/gifs/0001.gif');
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url) VALUES ('ex_cable_woodchopper', 'هیزم‌شکن چرخشی با سیم‌کش', 'Cable Woodchopper', 'core', 'شکم و میان‌تنه', 'cable', 'سیم‌کش', 'قدرت چرخشی پهلوها و هسته بدن', 'سرشانه', '۱. دسته سیم‌کش را با چرخش تنه از بالا به سمت زانوی مخالف هدایت کنید.', '/gifs/0245.gif');
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url) VALUES ('ex_air_bike', 'کرانچ دوچرخه (بایسیکل کرانچ)', 'Air Bike Crunch', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'درگیری همزمان شکم و پهلوها', 'فلکسور ران', '۱. روی کمر خوابیده و آرنج مخالف را به سمت زانوی مخالف هدایت کنید.', '/gifs/0003.gif');
